17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.DayOfWeek;
20	import java.time.LocalDate;
21	import java.util.ArrayList;
22	import java.util.Collection;
23	import java.util.List;
24	import java.util.regex.Pattern;
25	
26	import org.slf4j.Logger;
27	import org.slf4j.LoggerFactory;
28	import org.springframework.http.HttpHeaders;
29	import org.springframework.http.HttpStatus;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerHouseholdException;
32	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
33	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
34	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
35	import org.springframework.samples.petclinic.rest.advice.OwnerCityFullException;
36	import org.springframework.samples.petclinic.rest.advice.OwnerDailyLimitException;
37	import org.springframework.samples.petclinic.mapper.OwnerMapper;
38	import org.springframework.samples.petclinic.mapper.PetMapper;
39	import org.springframework.samples.petclinic.mapper.VisitMapper;
40	import org.springframework.samples.petclinic.model.Owner;
41	import org.springframework.samples.petclinic.model.Pet;
42	import org.springframework.samples.petclinic.model.Visit;
43	import org.springframework.samples.petclinic.rest.api.OwnersApi;
44	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
45	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
46	import org.springframework.samples.petclinic.rest.dto.PetDto;
47	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
48	import org.springframework.samples.petclinic.rest.dto.VisitDto;
49	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
50	import org.springframework.samples.petclinic.service.ClinicService;
51	import org.springframework.security.access.prepost.PreAuthorize;
52	import org.springframework.util.StringUtils;
53	import org.springframework.web.bind.annotation.CrossOrigin;
54	import org.springframework.web.bind.annotation.RequestMapping;
55	import org.springframework.web.bind.annotation.RestController;
56	import org.springframework.web.util.UriComponentsBuilder;
57	
58	import jakarta.transaction.Transactional;
59	
60	/**
61	 * @author Vitaliy Fedoriv
62	 */
63	
64	@RestController
65	@CrossOrigin(exposedHeaders = "errors, content-type")
66	@RequestMapping("/api")
67	public class OwnerRestControllerV1 implements OwnersApi {
68	
69	    /**
70	     * Basic syntactic check for an email address: a non-empty local part, an '@', and a domain with
71	     * at least one dot and a two-or-more letter top-level label. Case is ignored here; accepted
72	     * addresses are lower-cased before being stored.
73	     */
74	    private static final Pattern EMAIL_PATTERN =
75	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
76	
77	    /**
78	     * Dedicated logger for audit side-effects. Emitting audit records on a well-known, separately
79	     * named logger keeps them addressable independently of the class's diagnostic logging.
80	     */
81	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
82	
83	    /**
84	     * Maximum number of owners a single city may contain. A create that would take the owner's city
85	     * to more than this many owners - i.e. the city already holds this many - is rejected with a 409.
86	     */
87	    private static final int CITY_OWNER_LIMIT = 50;
88	
89	    /**
90	     * Maximum number of owners that may be registered on a single day. A create that would take the
91	     * number of owners sharing a {@code registrationDate} beyond this many - i.e. that many owners
92	     * have already been created that day - is rejected with a 429.
93	     */
94	    private static final int DAILY_OWNER_LIMIT = 100;
95	
96	    /**
97	     * Number of owners that must already have been created for a given day before the create
98	     * response flags a bulk sign-up. When more than this many owners already share a
99	     * {@code registrationDate}, the response's {@code bulkSignupWarning} is {@code true}.
100	     */
101	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
102	
103	    private final ClinicService clinicService;
104	
105	    private final OwnerMapper ownerMapper;
106	
107	    private final PetMapper petMapper;
108	
109	    private final VisitMapper visitMapper;
110	
111	    public OwnerRestControllerV1(ClinicService clinicService,
112	                                 OwnerMapper ownerMapper,
113	                                 PetMapper petMapper,
114	                                 VisitMapper visitMapper) {
115	        this.clinicService = clinicService;
116	        this.ownerMapper = ownerMapper;
117	        this.petMapper = petMapper;
118	        this.visitMapper = visitMapper;
119	    }
120	
121	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
122	    @Override
123	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
124	        Collection<Owner> owners;
125	        if (lastName != null) {
126	            owners = this.clinicService.findOwnerByLastName(lastName);
127	        } else {
128	            owners = this.clinicService.findAllOwners();
129	        }
130	        if (owners.isEmpty()) {
131	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
132	        }
133	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
134	    }
135	
136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Override
138	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
139	        Owner owner = this.clinicService.findOwnerById(ownerId);
140	        if (owner == null) {
141	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
142	        }
143	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
144	        ownerDto.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
145	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
146	    }
147	
148	    /**
149	     * Determines whether the supplied day currently holds more than {@link #BULK_SIGNUP_WARNING_THRESHOLD}
150	     * owners sharing that {@code registrationDate}, which flags an unusually high volume of same-day
151	     * owner sign-ups.
152	     *
153	     * @param registrationDate the day to inspect, or {@code null}
154	     * @return {@code true} when more than the threshold of owners are registered on that day
155	     */
156	    private boolean isBulkSignupDay(LocalDate registrationDate) {
157	        return registrationDate != null
158	            && countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
159	    }
160	
161	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
162	    @Override
163	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
164	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
165	        validateRequiredFields(ownerFieldsDto);
166	        HttpHeaders headers = new HttpHeaders();
167	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
168	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
169	        owner.setEmail(normalizeEmail(owner.getEmail()));
170	        if (owner.getRegistrationDate() == null) {
171	            owner.setRegistrationDate(LocalDate.now());
172	        }
173	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
174	        if (!this.clinicService.findOwnerByTelephone(owner.getTelephone()).isEmpty()) {
175	            throw new DuplicateOwnerTelephoneException(owner.getTelephone());
176	        }
177	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())
178	            && isDuplicateHousehold(owner.getLastName(), owner.getAddress())) {
179	            throw new DuplicateOwnerHouseholdException(owner.getLastName(), owner.getAddress());
180	        }
181	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
182	            throw new OwnerCityFullException(owner.getCity());
183	        }
184	        long ownersRegisteredOnDay = countOwnersRegisteredOn(owner.getRegistrationDate());
185	        if (ownersRegisteredOnDay >= DAILY_OWNER_LIMIT) {
186	            throw new OwnerDailyLimitException(owner.getRegistrationDate());
187	        }
188	        boolean bulkSignupWarning = ownersRegisteredOnDay > BULK_SIGNUP_WARNING_THRESHOLD;
189	        owner.setCustomerCode(buildCustomerCode(owner.getCity(), owner.getLastName()));
190	        owner.setHouseholdId(HouseholdNormalizer.householdId(owner.getLastName(), owner.getAddress()));
191	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
192	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
193	        this.clinicService.saveOwner(owner);
194	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
195	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
196	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
197	        ownerDto.setBulkSignupWarning(bulkSignupWarning);
198	        headers.setLocation(UriComponentsBuilder.newInstance()
199	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
200	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
201	    }
202	
203	    /**
204	     * Rejects an owner payload that is missing or blank in any required field. Collects the name of
205	     * every offending field and, if there is at least one, raises a {@link MissingOwnerFieldsException}
206	     * so the client receives a 400 whose {@code errors} array lists each missing field. The address is
207	     * checked in its {@link AddressNormalizer#normalize normalized} form, so a value that is blank only
208	     * after normalization is still rejected.
209	     *
210	     * @param ownerFieldsDto the submitted owner fields
211	     */
212	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
213	        List<String> missingFields = new ArrayList<>();
214	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
215	            missingFields.add("firstName");
216	        }
217	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
218	            missingFields.add("lastName");
219	        }
220	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
221	            missingFields.add("address");
222	        }
223	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
224	            missingFields.add("city");
225	        }
226	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
227	            missingFields.add("telephone");
228	        }
229	        if (!missingFields.isEmpty()) {
230	            throw new MissingOwnerFieldsException(missingFields);
231	        }
232	    }
233	
234	    /**
235	     * Normalizes an optional email address for owner creation. Email is optional, so a missing or
236	     * blank value is left untouched. When a value is supplied it must be a syntactically valid
237	     * address; the accepted value is lower-cased before it is stored and returned.
238	     *
239	     * @param email the raw email value submitted by the client, or {@code null}
240	     * @return the lower-cased email, or the original blank/{@code null} value when none was supplied
241	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
242	     */
243	    private String normalizeEmail(String email) {
244	        if (!StringUtils.hasText(email)) {
245	            return email;
246	        }
247	        if (!EMAIL_PATTERN.matcher(email).matches()) {
248	            throw new InvalidOwnerFieldsException(List.of("email"));
249	        }
250	        return email.toLowerCase();
251	    }
252	
253	    /**
254	     * Builds the owner's customer code formatted {@code <CITY3>-<LAST3>-<NNNN>}, where CITY3 is the
255	     * upper-cased first three letters of the city, LAST3 is the upper-cased first three letters of the
256	     * last name and NNNN is a per-city 4-digit zero-padded sequence equal to one more than the number
257	     * of owners already in that city (e.g. {@code SYD-SMI-0007}).
258	     *
259	     * @param city the owner's city
260	     * @param lastName the owner's last name
261	     * @return the assigned customer code
262	     */
263	    private String buildCustomerCode(String city, String lastName) {
264	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
265	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
266	        int sequence = (int) this.clinicService.findAllOwners().stream()
267	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
268	            .count() + 1;
269	        return String.format("%s-%s-%04d", city3, last3, sequence);
270	    }
271	
272	    /**
273	     * Determines whether an existing owner already shares a household with the supplied last name and
274	     * address. Two owners belong to the same household when {@link HouseholdNormalizer#sameHousehold}
275	     * considers their last name and address a match.
276	     *
277	     * @param lastName the submitted owner's last name
278	     * @param address the submitted owner's address
279	     * @return {@code true} if another owner already has the same normalized last name and address
280	     */
281	    /**
282	     * Counts how many owners already exist that share the supplied first and last name, compared
283	     * case-insensitively. This reflects the number of namesakes present <em>before</em> the current
284	     * owner is created and is stored on the new owner as its {@code namesakeCount}.
285	     *
286	     * @param firstName the submitted owner's first name
287	     * @param lastName the submitted owner's last name
288	     * @return the number of existing owners with the same first and last name, ignoring case
289	     */
290	    private int countNamesakes(String firstName, String lastName) {
291	        return (int) this.clinicService.findAllOwners().stream()
292	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
293	                && lastName.equalsIgnoreCase(existing.getLastName()))
294	            .count();
295	    }
296	
297	    private boolean isDuplicateHousehold(String lastName, String address) {
298	        return this.clinicService.findAllOwners().stream()
299	            .anyMatch(existing -> HouseholdNormalizer.sameHousehold(
300	                lastName, address, existing.getLastName(), existing.getAddress()));
301	    }
302	
303	    /**
304	     * Counts how many existing owners already belong to the supplied household, identified by its
305	     * {@code householdId}. Used when creating an owner to determine the household's size once the new
306	     * owner is added (this count plus one), which in turn drives the {@code GOLD} membership tier.
307	     *
308	     * @param householdId the normalized household identifier of the owner being created
309	     * @return the number of existing owners already sharing that {@code householdId}
310	     */
311	    private int countHouseholdMembers(String householdId) {
312	        return (int) this.clinicService.findAllOwners().stream()
313	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
314	            .count();
315	    }
316	
317	    /**
318	     * Counts how many owners already live in the supplied city, compared case-insensitively. Used to
319	     * enforce the per-city capacity limit when a new owner is created.
320	     *
321	     * @param city the submitted owner's city
322	     * @return the number of existing owners in that city, ignoring case
323	     */
324	    private long countOwnersInCity(String city) {
325	        return this.clinicService.findAllOwners().stream()
326	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
327	            .count();
328	    }
329	
330	    /**
331	     * Counts how many owners have already been created on the supplied registration date. Used to
332	     * enforce the per-day capacity limit when a new owner is created.
333	     *
334	     * @param registrationDate the registration date of the owner being created
335	     * @return the number of existing owners already registered on that date
336	     */
337	    /**
338	     * Rolls a registration date forward to a business day. A registration date must fall on a
339	     * business day, so when the supplied or defaulted date lands on a Saturday or Sunday it is
340	     * moved forward to the following Monday; a weekday is returned unchanged. Every value derived
341	     * from the registration date (such as the membership number's year segment) and the daily
342	     * create-limit therefore use the adjusted date.
343	     *
344	     * @param date the effective registration date, whether supplied or defaulted to the server date
345	     * @return the same date when it is a weekday, otherwise the next Monday
346	     */
347	    private LocalDate toBusinessDay(LocalDate date) {
348	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
349	            date = date.plusDays(1);
350	        }
351	        return date;
352	    }
353	
354	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
355	        return this.clinicService.findAllOwners().stream()
356	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
357	            .count();
358	    }
359	
360	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
361	    @Override
362	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
363	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
364	        if (currentOwner == null) {
365	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
366	        }
367	        currentOwner.setAddress(ownerFieldsDto.getAddress());
368	        currentOwner.setCity(ownerFieldsDto.getCity());
369	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
370	        currentOwner.setLastName(ownerFieldsDto.getLastName());
371	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
372	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
373	        this.clinicService.saveOwner(currentOwner);
374	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
375	    }
376	
377	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
378	    @Transactional
379	    @Override
380	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
381	        Owner owner = this.clinicService.findOwnerById(ownerId);
382	        if (owner == null) {
383	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
384	        }
385	        this.clinicService.deleteOwner(owner);
386	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
387	    }
388	
389	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
390	    @Override
391	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
392	        Owner owner = this.clinicService.findOwnerById(ownerId);
393	        if (owner == null) {
394	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
395	        }
396	        HttpHeaders headers = new HttpHeaders();
397	        Pet pet = petMapper.toPet(petFieldsDto);
398	        owner.setId(ownerId);
399	        pet.setOwner(owner);
400	        pet.getType().setName(null);
401	        this.clinicService.savePet(pet);
402	        PetDto petDto = petMapper.toPetDto(pet);
403	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
404	            .buildAndExpand(pet.getId()).toUri());
405	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
406	    }
407	
408	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
409	    @Override
410	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
411	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
412	        if (currentOwner != null) {
413	            Pet currentPet = this.clinicService.findPetById(petId);
414	            if (currentPet != null) {
415	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
416	                currentPet.setName(petFieldsDto.getName());
417	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
418	                this.clinicService.savePet(currentPet);
419	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
420	            }
421	        }
422	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
423	    }
424	
425	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
426	    @Override
427	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
428	        HttpHeaders headers = new HttpHeaders();
429	        Visit visit = visitMapper.toVisit(visitFieldsDto);
430	        Pet pet = new Pet();
431	        pet.setId(petId);
432	        visit.setPet(pet);
433	        this.clinicService.saveVisit(visit);
434	        VisitDto visitDto = visitMapper.toVisitDto(visit);
435	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
436	            .buildAndExpand(visit.getId()).toUri());
437	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
438	    }
439	
440	
441	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
442	    @Override
443	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
444	        Owner owner = this.clinicService.findOwnerById(ownerId);
445	        if (owner != null) {
446	            Pet pet = owner.getPet(petId);
447	            if (pet != null) {
448	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
449	            }
450	        }
451	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
452	    }
453	}
